-- Create "webforms" table
CREATE TABLE `webforms` (`id` int unsigned NOT NULL AUTO_INCREMENT, `description` mediumtext NULL, `confirmation` mediumtext NULL, `confirmation_url` varchar(500) NOT NULL DEFAULT '', `submit_label` varchar(128) NOT NULL DEFAULT '', `closed` bool NOT NULL DEFAULT false, `notify_email` varchar(500) NOT NULL DEFAULT '', `limit_per_user` bool NOT NULL DEFAULT false, `max_submissions` int NOT NULL DEFAULT 0, `closes_at` datetime NULL, `nid` int unsigned NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `webforms_nid` (`nid`), CONSTRAINT `webforms_nodes_node` FOREIGN KEY (`nid`) REFERENCES `nodes` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "webform_elements" table
CREATE TABLE `webform_elements` (`id` int unsigned NOT NULL AUTO_INCREMENT, `machine_name` varchar(64) NOT NULL, `type` varchar(32) NOT NULL, `label` varchar(500) NOT NULL, `description` text NULL, `required` bool NOT NULL DEFAULT false, `options` text NULL, `weight` int NOT NULL DEFAULT 0, `visible_if_element` varchar(64) NOT NULL DEFAULT '', `visible_if_value` varchar(500) NOT NULL DEFAULT '', `prefill_param` varchar(64) NOT NULL DEFAULT '', `webform_id` int unsigned NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `webform_elements_key` (`webform_id`, `machine_name`), CONSTRAINT `webform_elements_webforms_elements` FOREIGN KEY (`webform_id`) REFERENCES `webforms` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "webform_submissions" table
CREATE TABLE `webform_submissions` (`id` int unsigned NOT NULL AUTO_INCREMENT, `remote_ip` varchar(64) NOT NULL DEFAULT '', `source_url` varchar(500) NOT NULL DEFAULT '', `created_at` datetime NOT NULL, `webform_id` int unsigned NOT NULL, `user_id` int unsigned NULL, PRIMARY KEY (`id`), INDEX `webformsubmission_webform_id_created_at` (`webform_id`, `created_at`), INDEX `webformsubmission_user_id` (`user_id`), CONSTRAINT `webform_submissions_webforms_submissions` FOREIGN KEY (`webform_id`) REFERENCES `webforms` (`id`) ON DELETE CASCADE, CONSTRAINT `webform_submissions_users_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "webform_submission_values" table
CREATE TABLE `webform_submission_values` (`id` int unsigned NOT NULL AUTO_INCREMENT, `delta` int NOT NULL DEFAULT 0, `value` mediumtext NOT NULL, `element_id` int unsigned NOT NULL, `submission_id` int unsigned NOT NULL, PRIMARY KEY (`id`), INDEX `webformsubmissionvalue_element_id` (`element_id`), INDEX `webformsubmissionvalue_submission_id` (`submission_id`), CONSTRAINT `webform_submission_values_webform_elements_values` FOREIGN KEY (`element_id`) REFERENCES `webform_elements` (`id`) ON DELETE CASCADE, CONSTRAINT `webform_submission_values_webform_submissions_values` FOREIGN KEY (`submission_id`) REFERENCES `webform_submissions` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
